						  create_targetted_legacy_effect(player, instance->parent_card, empty, player, nightmare);
						  add_a_subtype_permanently(player, card, player, nightmare, SUBTYPE_NIGHTMARE);
						  put_into_play(player, nightmare);
						}
					  else
						spell_fizzled = 1;
					}
				  break;
				}

