				{
				  int i, leg = 0, idx = 0;
				  for (i = 0; i < active_cards_count[1-player]; ++i)
					if (in_hand(1-player, i))
					  {
						ashiok_exiledby_remember(player, instance->parent_card, 1-player, get_card_instance(1-player, i)->internal_card_id, &leg, &idx);
