{
  /* Phyrexian Boon	|2|B
   * Enchantment - Aura
   * Enchant creature
   * Enchanted creature gets +2/+1 as long as it's |Sblack. Otherwise, it gets -1/-2. */

  if (event == EVENT_POWER || event == EVENT_TOUGHNESS || event == EVENT_SHOULD_AI_PLAY)
	{
	  card_instance_t* instance;
	  if (!(instance = in_play(player, card))
